    IF v_sort IS NULL OR NOT (v_sort = ANY (ARRAY['firm_name', 'contact_person', 'email', 'mobile', 'irdai_registration_no', 'registration_expiry_date', 'gst_number', 'address_line', 'city', 'state', 'commission_percent', 'id', 'created_date', 'modified_date', 'is_active', 'broker_code'])) THEN
        v_sort := 'created_date';
