    IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
        v_like := '%' || btrim(p_search) || '%';
        v_where := v_where || format(' AND (broker_code::text ILIKE %1$L OR firm_name::text ILIKE %1$L OR contact_person::text ILIKE %1$L OR email::text ILIKE %1$L OR mobile::text ILIKE %1$L OR irdai_registration_no::text ILIKE %1$L OR city::text ILIKE %1$L)', v_like);
    END IF;

    FOR v_key, v_val IN SELECT key, value FROM jsonb_each_text(COALESCE(p_filters, '{}'::jsonb)) LOOP
        v_col := learninsurancedb.fn_to_snake(v_key);
        IF v_col = ANY (ARRAY['is_active', 'city', 'state']) AND COALESCE(v_val, '') <> '' THEN
            v_where := v_where || format(' AND %I::text = %L', v_col, v_val);
        END IF;
    END LOOP;

    EXECUTE format('SELECT count(*) FROM learninsurancedb.vw_brokers %s', v_where) INTO v_total;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(learninsurancedb.fn_to_camel(to_jsonb(q))), ''[]''::jsonb)
