-- CREATE: p_data uses camelCase keys
CREATE OR REPLACE FUNCTION learninsurancedb.fn_broker_create(p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE v_id bigint;
BEGIN
    INSERT INTO learninsurancedb.brokers (firm_name, contact_person, email, mobile, irdai_registration_no, registration_expiry_date, gst_number, address_line, city, state, commission_percent, created_by)
    VALUES (NULLIF(p_data->>'firmName', ''),
            NULLIF(p_data->>'contactPerson', ''),
            NULLIF(p_data->>'email', ''),
            NULLIF(p_data->>'mobile', ''),
            NULLIF(p_data->>'irdaiRegistrationNo', ''),
            NULLIF(p_data->>'registrationExpiryDate', '')::date,
            NULLIF(p_data->>'gstNumber', ''),
            NULLIF(p_data->>'addressLine', ''),
            NULLIF(p_data->>'city', ''),
            NULLIF(p_data->>'state', ''),
            COALESCE(NULLIF(p_data->>'commissionPercent', '')::numeric, 15),
            COALESCE(p_user, 'system'))
    RETURNING id INTO v_id;
    RETURN learninsurancedb.fn_broker_get_by_id(v_id);
END
$fn$;


-- UPDATE: only keys present in p_data are changed (so partial and full updates both work)
CREATE OR REPLACE FUNCTION learninsurancedb.fn_broker_update(p_id bigint, p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.brokers SET
        firm_name = CASE WHEN p_data ? 'firmName' THEN NULLIF(p_data->>'firmName', '') ELSE firm_name END,
        contact_person = CASE WHEN p_data ? 'contactPerson' THEN NULLIF(p_data->>'contactPerson', '') ELSE contact_person END,
        email = CASE WHEN p_data ? 'email' THEN NULLIF(p_data->>'email', '') ELSE email END,
        mobile = CASE WHEN p_data ? 'mobile' THEN NULLIF(p_data->>'mobile', '') ELSE mobile END,
        irdai_registration_no = CASE WHEN p_data ? 'irdaiRegistrationNo' THEN NULLIF(p_data->>'irdaiRegistrationNo', '') ELSE irdai_registration_no END,
        registration_expiry_date = CASE WHEN p_data ? 'registrationExpiryDate' THEN NULLIF(p_data->>'registrationExpiryDate', '')::date ELSE registration_expiry_date END,
        gst_number = CASE WHEN p_data ? 'gstNumber' THEN NULLIF(p_data->>'gstNumber', '') ELSE gst_number END,
        address_line = CASE WHEN p_data ? 'addressLine' THEN NULLIF(p_data->>'addressLine', '') ELSE address_line END,
        city = CASE WHEN p_data ? 'city' THEN NULLIF(p_data->>'city', '') ELSE city END,
        state = CASE WHEN p_data ? 'state' THEN NULLIF(p_data->>'state', '') ELSE state END,
        commission_percent = CASE WHEN p_data ? 'commissionPercent' THEN COALESCE(NULLIF(p_data->>'commissionPercent', '')::numeric, 15) ELSE commission_percent END,
        modified_date = now(),
        modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Broker % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_broker_get_by_id(p_id);
END
$fn$;


-- SET ACTIVE: soft delete / restore
CREATE OR REPLACE FUNCTION learninsurancedb.fn_broker_set_active(p_id bigint, p_active boolean, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.brokers SET is_active = p_active, modified_date = now(), modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Broker % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_broker_get_by_id(p_id);
END
$fn$;

-- DELETE (soft): sets is_active = false
CREATE OR REPLACE FUNCTION learninsurancedb.fn_broker_delete(p_id bigint, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM learninsurancedb.fn_broker_set_active(p_id, FALSE, p_user);
